from pathlib import Path
import json,statistics,sqlite3,hashlib,time
from urllib.request import urlopen
S=json.loads(Path('/tmp/task010-completion/state.json').read_text());OUT=Path(S['evidence'])
trials=json.loads((OUT/'latency-trials.json').read_text());rows=[r for r in trials if not r['pilot']];events=[json.loads(x) for x in (OUT/'events-v2.jsonl').read_text().splitlines()];browser=[json.loads(x) for x in (OUT/'latency-events-v4.jsonl').read_text().splitlines()]
assert len(rows)==10 and [r['id'] for r in rows]==['sample-'+str(i) for i in range(1,11)]
checks=[]
for r in rows:
 render=r['render'];api=r['api']['node'];boot,seq=[x.strip() for x in render['key'].split('/')];mqtt=[e for e in events if e['source']=='mqtt' and e.get('topic','').endswith('/telemetry') and e.get('body',{}).get('boot_id')==boot and str(e.get('body',{}).get('seq'))==seq];assert len(mqtt)==1,r['id'];m=mqtt[0]
 raw=int(''.join(x for x in render['readings']['LDR · ADC raw'] if x.isdigit()));assert raw==api['telemetry']['ldr_adc']==m['body']['ldr_adc']
 assert int(seq)>int(r['baseline']['seq']) and boot==r['baseline']['boot_id']
 assert m['host_ms']>r['action_host_interval_ms'][1]
 visibility=[e for e in browser if e['event']=='dashboard_visibility' and e['host_ms']<=r['action_host_interval_ms'][0]];assert visibility and visibility[-1]['visibility']=='visible'
 hidden=[e for e in browser if e['event']=='dashboard_visibility' and e['visibility']=='hidden' and r['action_host_interval_ms'][0]<=e['host_ms']<=render['host_ms']];assert not hidden
 assert r['status']=='PASS' and r['latency_interval_ms'][0]>=0 and r['latency_interval_ms'][1]<=3000 and not r['reasons']
 checks.append({'id':r['id'],'boot_id':boot,'seq':seq,'adc':raw,'action_host_interval_ms':r['action_host_interval_ms'],'mqtt_host_ms':m['host_ms'],'api_received_at':api['last_seen'],'dom_browser_ms':render['browser_ms'],'latency_interval_ms':r['latency_interval_ms'],'mqtt_api_dom_match':True,'visibility_valid':True})
summary={'result':'PASS','method':'Trusted native LDR keyboard Home/End in Wokwi VSCode; calibrated browser clock intervals; matching real MQTT/API/DOM after two rAF; video corroboration','source':'latency-trials.json; latency-events-v4.jsonl; events-v2.jsonl','threshold_ms':3000,'qualified_samples':10,'required_samples':10,'pilot_samples_excluded':2,'median_interval_ms':[statistics.median(r['latency_interval_ms'][i] for r in rows) for i in [0,1]],'max_interval_ms':[max(r['latency_interval_ms'][i] for r in rows) for i in [0,1]],'samples':checks,'dashboard_uncaught_exceptions':sum(e['event']=='dashboard_pageerror' for e in browser),'conditions':{'sensor_levels_lux':[0.1,100000],'sensor_level_note':'Fallback native Home/End extrema give discrete observable actions; source/timers/thresholds unchanged','simulation':'one ESP32 node_01, original esp32dev BIN/ELF; VSCode display approximately99–100% speed','viewport':'two owned windows960x1040 side-by-side; actual dashboard viewport; LDR visible throughout','clocks':'Host wall clock with browser offset bounds sampled before/after each trial; never subtract node uptime from wall time','serial_note':'Bounded Serial observer corroborates outage/AUTO; latency origin is trusted sensor UI action, not Serial receipt','orchestration_note':'Foreground driver exited143 after eight samples; persistent controller retained all; resumed only samples9/10 with unchanged predeclared delays. No sample repeated or omitted.'}}
(OUT/'latency-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
terminal=[e for e in events if e['event']=='ui_terminal'];assert {e['api']['result'] for e in terminal}=={'REJECTED','TIMEOUT'}
restart=[e for e in events if e['event']=='pending_restart_result'];assert restart and restart[-1]['reason']=='BACKEND_RESTART' and restart[-1]['open_experiment_restored_after_reload'] and restart[-1]['experiment_stopped']
recovery=json.loads((OUT/'broker-recovery-audit.json').read_text());assert recovery['result']=='PASS' and recovery['same_boot'] and recovery['old_command_publish_after_reconnect']==0
serial=[json.loads(x) for x in (OUT/'serial.jsonl').read_text().splitlines()];start=next(e for e in events if e['event']=='broker_outage_started');action=next(e for e in events if e['event']=='offline_sensor_action');service=[json.loads(x) for x in (OUT/'service-actions.jsonl').read_text().splitlines()];up=next(e['host_ms'] for e in service if e['event']=='broker_start')
night=[e for e in serial if start['action']['end_ms']<e['host_ms']<action['begin_ms'] and e.get('fields',{}).get('mqtt')=='0' and e['fields'].get('environment')=='NIGHT' and e['fields'].get('applied')=='25'];day=[e for e in serial if action['end_ms']<e['host_ms']<up and e.get('fields',{}).get('mqtt')=='0' and e['fields'].get('environment')=='DAY' and e['fields'].get('applied')=='0'];assert night and day
(OUT/'offline-auto-causal-audit.json').write_text(json.dumps({'result':'PASS','broker_down':start['action'],'sensor_action':action,'night_before_action':night[-1],'day_after_action':day[0],'broker_restarted_host_ms':up},ensure_ascii=False,indent=2)+'\n')
db=sqlite3.connect('file:/tmp/task010-completion/qa.db?mode=ro',uri=True);db.row_factory=sqlite3.Row
snapshot={'at_host_ms':time.time()*1000,'database':'QA-only /tmp/task010-completion/qa.db','quick_check':db.execute('pragma quick_check').fetchone()[0],'commands':[dict(r) for r in db.execute('select command_id,result,reason,attempts,created_at,sent_at,ack_at from commands')],'experiments':[dict(r) for r in db.execute('select * from experiments')],'quality_counts':[dict(r) for r in db.execute('select quality,count(*) as count from telemetry group by quality')],'health':json.load(urlopen('http://127.0.0.1:8001/api/health')),'nodes':json.load(urlopen('http://127.0.0.1:8001/api/nodes'))};db.close();assert all(r['result']!='PENDING' for r in snapshot['commands']);assert all(r['ended_at'] for r in snapshot['experiments']);assert snapshot['quick_check']=='ok'
(OUT/'qa-final-snapshot.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2)+'\n')
result={'task':'TASK-010','status':'PASS','acceptance_groups':[{'id':1,'status':'PASS','basis':'Historical integration plus current real QA flow'},{'id':2,'status':'PASS','basis':'Live terminal UI, broker outage/reconnect/no replay, Serial AUTO offline; previous MANUAL/60s preserved'},{'id':3,'status':'PASS','basis':'Historical data/CSV/gap plus current pending/open experiment restart and session race fix'},{'id':4,'status':'PASS','basis':'10 current sensor→dashboard samples plus 10 prior command→ACK samples'}],'new_backend_tests':72,'backend_warning':'Existing TestClient/HTTPX deprecation warning unchanged','latency':{'samples':10,'median_interval_ms':summary['median_interval_ms'],'max_interval_ms':summary['max_interval_ms']},'source_limit':'Wokwi simulation; not physical hardware, three nodes or EX-series','cleanup_pending':True}
(OUT/'acceptance-audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'acceptance':'4/4 live groups checked','sensor_latency':result['latency'],'pending_commands':0,'open_qa_experiments':0,'quick_check':'ok'},ensure_ascii=False))
